INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q2733432', 'Battle of São Mamede', 'The Battle of São Mamede (Portuguese: Batalha de São Mamede) took place on 24 June 1128 near Guimarães and is considered an important event in the process that led to the establishment of Portugal as an independent kingdom. Forces led by Afonso Henriques defeated forces led by his mother, Theresa of Portugal, and Fernão Peres de Trava.', 1128, 6, 24, NULL, NULL, NULL, 'day', '24 June 1128', 56, 'https://en.wikipedia.org/wiki/Battle_of_S%C3%A3o_Mamede'),
  ('Q1328537', 'Battle of Ourique', 'The Battle of Ourique (Portuguese: Batalha de Ourique; Arabic: معركة أوريكه) was fought on 25 July 1139, when Portuguese forces under Afonso Henriques defeated forces led by the Almoravid wāli (governor) of Córdoba, Muhammad Az-Zubayr Ibn Umar, who is identified as "King Ismar" in Christian chronicles. The exact location of the battle remains uncertain and has been the subject of considerable debate.', 1139, 7, 25, NULL, NULL, NULL, 'day', '25 July 1139', 62, 'https://en.wikipedia.org/wiki/Battle_of_Ourique'),
  ('Q815177', 'Siege of Lisbon', 'The siege of Lisbon, from 1 July to 25 October 1147, was the military action against the Almoravid dynasty that brought the city of Lisbon under the definitive control of the new Christian power, the Kingdom of Portugal. It is seen as a pivotal battle of the wider Reconquista.', 1147, 10, 25, 1147, 10, 25, 'day', '25 October 1147', 65, 'https://en.wikipedia.org/wiki/Siege_of_Lisbon'),
  ('Q5162445', 'Conquest of Santarém', 'The conquest of Santarém took place on 15 March 1147, when the troops of the Kingdom of Portugal under the leadership of Afonso I of Portugal captured the Almoravid city of Santarém (at the time called Shantarin).', 1147, 3, 14, 1147, 3, 15, 'day', '14 March 1147 – 15 March 1147', 45, 'https://en.wikipedia.org/wiki/Conquest_of_Santar%C3%A9m'),
  ('Q1365483', 'Treaty of Alcañices', 'The Treaty of Alcañices or Treaty of Alcanises was signed in Alcañices between King Denis of Portugal and King Fernando IV of Castile in 1297. Denis was the grandson of King Alfonso X of Castile and essentially an administrator and not a warrior king.', 1297, 9, 12, NULL, NULL, NULL, 'day', '12 September 1297', 48, 'https://en.wikipedia.org/wiki/Treaty_of_Alca%C3%B1ices'),
  ('Q2105495', '1383–1385 Portuguese Interregnum', 'An interregnum and a war of succession began in the Kingdom of Portugal in 1383 when King Ferdinand I died leaving no sons and ended when King John I was crowned in 1385 after his victory during the Battle of Aljubarrota. The Portuguese interpret the era as their earliest national resistance movement to counter Castilian intervention, and Robert Durand considers it as the "great revealer of national consciousness".', 1383, 4, 2, 1385, 10, NULL, 'day', '2 April 1383 – October 1385', 57, 'https://en.wikipedia.org/wiki/1383%E2%80%931385_Portuguese_interregnum'),
  ('Q2530225', 'Battle of Atoleiros', 'The Battle of Atoleiros (Portuguese pronunciation: [ɐtuˈlɐjɾuʃ]) took place on 6 April 1384, between a Portuguese force and a punitive expedition from Castile sent by John I. The battle took place near the population centre of Fronteira in Alentejo. It was the first major battle of the 1383–1385 Crisis.', 1384, 4, 6, NULL, NULL, NULL, 'day', '6 April 1384', 50, 'https://en.wikipedia.org/wiki/Battle_of_Atoleiros'),
  ('Q7510200', 'Siege of Lisbon', 'The siege of Lisbon was a siege of the city of Lisbon from 29 May to 3 September 1384. It was a part of the 1383-1385 Crisis, and occurred between the Portuguese defenders of the city led by John I of Portugal and the Castilian army led by King John I of Castile.', 1384, 5, 29, 1384, 9, 3, 'day', '29 May 1384 – 3 September 1384', 45, 'https://en.wikipedia.org/wiki/Siege_of_Lisbon_(1384)'),
  ('Q1341972', 'Battle of Aljubarrota', 'The Battle of Aljubarrota was fought between the Kingdom of Portugal and the Crown of Castile on 14 August 1385. Forces commanded by King John I of Portugal and his Constable Nuno Álvares Pereira, with the support of English allies, opposed the army of King John I of Castile with its Aragonese and French allies, as well as Genoese mercenaries at São Jorge, between the towns of Leiria and Alcobaça, in central Portugal.', 1385, 8, 14, NULL, NULL, NULL, 'day', '14 August 1385', 64, 'https://en.wikipedia.org/wiki/Battle_of_Aljubarrota'),
  ('Q4087472', 'Battle of Trancoso', 'The Battle of Trancoso was fought on 29 May 1385 between the Kingdom of Portugal and the Crown of Castile. Following the coronation of João of Aviz, John I of Castile sent an army into the Portuguese region of Beira in retaliation for Portuguese defiance, where they committed all the kinds of atrocities.', 1385, 5, 29, NULL, NULL, NULL, 'day', '29 May 1385', 41, 'https://en.wikipedia.org/wiki/Battle_of_Trancoso'),
  ('Q2887822', 'Battle of Alfarrobeira', 'The Battle of Alfarrobeira (Portuguese pronunciation: [alfɐʁuˈβɐjɾɐ]) took place on 20 May 1449. It was a confrontation between the forces commanded by King Afonso V of Portugal and his uncle Afonso, Duke of Braganza, against the army of the rebellious Peter, Duke of Coimbra.', 1449, 5, 20, NULL, NULL, NULL, 'day', '20 May 1449', 47, 'https://en.wikipedia.org/wiki/Battle_of_Alfarrobeira'),
  ('Q15138579', 'Persecution of Jews and Muslims by Manuel I of Portugal', 'On 5 December 1496, King Manuel I of Portugal signed the decree of expulsion of Jews and Muslims to take effect by the end of October of the next year.', 1496, 12, 5, NULL, NULL, NULL, 'day', '5 December 1496', 45, 'https://en.wikipedia.org/wiki/Persecution_of_Jews_and_Muslims_by_Manuel_I_of_Portugal'),
  ('Q1147471', 'Treaty of Zaragoza', 'The Treaty of Zaragoza or Saragossa, also called the Capitulation of Zaragoza or Saragossa, was a peace treaty between Castile and Portugal, signed on 22 April 1529 by King John III of Portugal and the Habsburg Emperor Charles V in the Aragonese city of Zaragoza. The treaty defined the areas of Castilian and Portuguese influence in Asia in order to resolve the "Moluccas issue", which had arisen because both kingdoms claimed the lucrative Spice Islands (now Indonesia''s Malukus) for themselves, asserting that they were within their area of influence as specified in 1494 by the Treaty of…', 1529, 4, 22, NULL, NULL, NULL, 'day', '22 April 1529', 70, 'https://en.wikipedia.org/wiki/Treaty_of_Zaragoza'),
  ('Q741788', 'Battle of Alcântara', 'The Battle of Alcântara took place on 25 August 1580, near the brook of Alcântara, in the vicinity of Lisbon, Portugal, and was a victory of the King of Habsburg Spain Philip II over the other pretender to the Portuguese throne, Dom António, Prior of Crato.', 1580, 8, 25, NULL, NULL, NULL, 'day', '25 August 1580', 43, 'https://en.wikipedia.org/wiki/Battle_of_Alc%C3%A2ntara_(1580)'),
  ('Q3099190', 'Battle of Ponta Delgada', 'The naval Battle of Vila Franca do Campo, also known as Battle of Ponta Delgada and Naval Battle of Terceira Island, took place on 26 July 1582, off the coast of the island of São Miguel in the Portuguese archipelago of the Azores, during the War of the Portuguese Succession. A combined corsair expedition, mainly French (a French, and English fleet with Portuguese forces included), sailed against a Spanish naval force made up of Portuguese and Castilian ships, to preserve control of the Azores under the pretender António, Prior of Crato and to defend the islands from incorporation into the…', 1582, 7, 26, NULL, NULL, NULL, 'day', '26 July 1582', 48, 'https://en.wikipedia.org/wiki/Battle_of_Vila_Franca_do_Campo'),
  ('Q4871029', 'Battle of Flores', 'The Battle of Flores was a naval engagement during the Brittany Campaign of the Anglo-Spanish War of 1585 fought off the Island of Flores between an English fleet of 22 ships under Lord Thomas Howard and a Spanish fleet of 55 ships under Alonso de Bazán. Sent to the Azores to capture the annual Spanish treasure convoy, when a stronger Spanish fleet appeared off Flores, Howard ordered his ships to flee to the north, saving all of them except the galleon Revenge commanded by Admiral Sir Richard Grenville.', 1591, 8, 30, 1591, 9, 1, 'day', '30 August 1591 – 1 September 1591', 47, 'https://en.wikipedia.org/wiki/Battle_of_Flores_(1591)'),
  ('Q2887851', 'Battle of Ameixial', 'The Battle of Ameixial, was fought on 8 June 1663, near the village of Santa Vitória do Ameixial, some 10 kilometres (6.2 mi) north-west of Estremoz, between Spanish and Portuguese as part of the Portuguese Restoration War. In Spain, the battle is better known as the Battle of Estremoz.', 1663, 6, 8, NULL, NULL, NULL, 'day', '8 June 1663', 39, 'https://en.wikipedia.org/wiki/Battle_of_Ameixial'),
  ('Q2889383', 'Battle of Montes Claros', 'The Battle of Montes Claros was fought on 17 June 1665, near Borba, between Spanish and a combined Anglo-Portuguese force as the last major battle in the Portuguese Restoration War. The battle resulted in a decisive Portuguese victory and is considered one of the most important battles in the country''s history.', 1665, 6, 17, NULL, NULL, NULL, 'day', '17 June 1665', 41, 'https://en.wikipedia.org/wiki/Battle_of_Montes_Claros'),
  ('Q1456443', 'Treaty of Lisbon', 'The Treaty of Lisbon of 1668 was a peace treaty between Portugal and Spain that was concluded at Lisbon on 13 February 1668 with the mediation of England in which Spain recognised the sovereignty of Portugal''s new ruling dynasty, the House of Braganza. The regent of Spain, Queen Mariana of Austria, the second wife of the late King Philip IV, acted in the name of her young son, Charles II and oversaw the negotiations on the behalf of Spain.', 1668, 2, 13, NULL, NULL, NULL, 'day', '13 February 1668', 52, 'https://en.wikipedia.org/wiki/Treaty_of_Lisbon_(1668)'),
  ('Q1164835', 'Battle of Lagos', 'The Battle of Lagos was fought during the Nine Years'' War on 27 June 1693 (17 June 1693 O.S.), when a French fleet under Anne Hilarion de Tourville defeated an Anglo-Dutch fleet under George Rooke near Lagos Bay in Portugal. Rooke''s squadron was protecting the Smyrna convoy, and it is by this name that the action is sometimes known.', 1693, 6, 27, NULL, NULL, NULL, 'day', '27 June 1693', 45, 'https://en.wikipedia.org/wiki/Battle_of_Lagos_(1693)'),
  ('Q1435156', 'Methuen Treaty', 'The Methuen Treaty was a military and commercial treaty between England and Portugal signed in 1703 as part of the War of the Spanish Succession. Named after John Methuen, it actually refers to two treaties signed that year.', 1703, 12, 27, NULL, NULL, NULL, 'day', '27 December 1703', 56, 'https://en.wikipedia.org/wiki/Methuen_Treaty'),
  ('Q2890537', 'Battle of La Gudiña', 'The Battle of La Gudiña, Battle of Val Gudina, or Battle of Campo Maior (Spanish: Batalla de La Gudiña; Portuguese: Batalha de Caia), was fought on 7 May 1709 near Arronches between the Spanish Bourbon army of Extremadura, under the Marquis de Bay, and the Portuguese and British, under the Huguenot Earl of Galway and the Marquis of Fronteira. This battle resulted in a crushing defeat for the Anglo-Portuguese army, 4,000-5,000 soldiers were killed, wounded or captured, while the Spanish had only 400 soldiers dead or wounded.', 1709, 5, 7, NULL, NULL, NULL, 'day', '7 May 1709', 41, 'https://en.wikipedia.org/wiki/Battle_of_La_Gudi%C3%B1a'),
  ('Q4870652', 'Battle of Cape St. Vincent', 'The Battle of Cape St Vincent was fought on 20 December 1719 as part of the War of the Quadruple Alliance. Occurring off Cape St.', 1719, 12, 20, NULL, NULL, NULL, 'day', '20 December 1719', 43, 'https://en.wikipedia.org/wiki/Battle_of_Cape_St._Vincent_(1719)'),
  ('Q191055', '1755 Lisbon earthquake', 'The 1755 Lisbon earthquake, also known as the Great Lisbon earthquake, occurred in the Iberian Peninsula and Northwest Africa area on the morning of Saturday, 1 November, 1755 (on the Christian Feast of All Saints); it took place at approximately 09:40 local time. In combination with subsequent fires and a tsunami, the earthquake almost completely destroyed Lisbon and adjoining areas.', 1755, 11, 1, NULL, NULL, NULL, 'day', '1 November 1755', 77, 'https://en.wikipedia.org/wiki/1755_Lisbon_earthquake'),
  ('Q464226', 'Battle of Lagos', 'The Battle of Lagos took place between a British fleet commanded by Edward Boscawen and a French fleet under Jean-François de La Clue-Sabran over two days in 1759 during the Seven Years'' War. They fought south west of the Gulf of Cádiz on 18 August and to the east of the small Portuguese port of Lagos, after which the battle is named, on 19 August.', 1759, 8, 19, NULL, NULL, NULL, 'day', '19 August 1759', 53, 'https://en.wikipedia.org/wiki/Battle_of_Lagos'),
  ('Q178912', 'Battle of Cape St. Vincent', 'The Battle of Cape St. Vincent (Spanish: Batalla del Cabo de San Vicente) was a fleet action fought off Cape St.', 1780, 1, 16, NULL, NULL, NULL, 'day', '16 January 1780', 55, 'https://en.wikipedia.org/wiki/Battle_of_Cape_St._Vincent_(1780)'),
  ('Q373401', 'Battle of Cape St. Vincent', 'The Battle of Cape St. Vincent was a fleet action fought on 14 February 1797 between the British and Spanish navies off Cape St.', 1797, 2, 14, NULL, NULL, NULL, 'day', '14 February 1797', 57, 'https://en.wikipedia.org/wiki/Battle_of_Cape_St._Vincent_(1797)'),
  ('Q209359', 'Battle of Vimeiro', 'In the Battle of Vimeiro (sometimes shown as "Vimiera" or "Vimeira" in contemporary British texts) on 21 August 1808, the British under General Arthur Wellesley (who later became the Duke of Wellington) defeated the French under Major-General Jean-Andoche Junot near the village of Vimeiro (Portuguese pronunciation: [viˈmɐjɾu]), near Lisbon, Portugal, during the Peninsular War. This battle put an end to the first French invasion of Portugal.', 1808, 8, 21, NULL, NULL, NULL, 'day', '21 August 1808', 55, 'https://en.wikipedia.org/wiki/Battle_of_Vimeiro'),
  ('Q245874', 'Battle of Évora', 'The Battle of Évora (29 July 1808) saw an Imperial French division under Louis Henri Loison attack a combined Portuguese-Spanish force led by Francisco de Paula Leite de Sousa. Encountering Leite''s smaller body of soldiers outside Évora, the French easily brushed them aside and went on to storm the city, which was held by poorly armed townsmen and militia.', 1808, 7, 29, NULL, NULL, NULL, 'day', '29 July 1808', 43, 'https://en.wikipedia.org/wiki/Battle_of_%C3%89vora_(1808)'),
  ('Q324344', 'Battle of Roliça', 'At the Battle of Roliça (17 August 1808), the first battle fought by the British army during the Peninsular War, an Anglo-Portuguese army under Sir Arthur Wellesley defeated an outnumbered Imperial French division under General of Division Henri François Delaborde, near the village of Roliça in Portugal. The French retired in good order.', 1808, 8, 17, NULL, NULL, NULL, 'day', '17 August 1808', 50, 'https://en.wikipedia.org/wiki/Battle_of_Roli%C3%A7a'),
  ('Q233405', 'Second Battle of Porto', 'The Second Battle of Porto, also known as the Battle of the Douro or the Crossing of the Douro, took place on 12 May 1809. General Arthur Wellesley''s Anglo-Portuguese Army defeated Marshal Soult''s French troops and took back the city of Porto.', 1809, 5, 12, NULL, NULL, NULL, 'day', '12 May 1809', 45, 'https://en.wikipedia.org/wiki/Second_Battle_of_Porto'),
  ('Q1532629', 'Battle of Braga', 'The Battle of Braga or Battle of Póvoa de Lanhoso or Battle of Carvalho d''Este (20 March 1809) saw an Imperial French corps led by Marshal Jean-de-Dieu Soult attack a Portuguese army commanded by Baron Eben. When Soult''s professional soldiers attacked, the Portuguese at first fought back but soon ran away.', 1809, 3, 20, NULL, NULL, NULL, 'day', '20 March 1809', 41, 'https://en.wikipedia.org/wiki/Battle_of_Braga_(1809)'),
  ('Q1632116', 'First Battle of Porto', 'In the First Battle of Porto (29 March 1809) the French under Marshal Soult defeated the Portuguese, under General Parreiras, outside the city of Porto during the Peninsular War. Soult followed up his success by storming the city, in the course of which thousands of fleeing citizens drowned in the Porto Boat Bridge disaster.', 1809, 3, 28, NULL, NULL, NULL, 'day', '28 March 1809', 43, 'https://en.wikipedia.org/wiki/First_Battle_of_Porto'),
  ('Q389349', 'Battle of Bussaco', 'The Battle of Buçaco (pronounced [buˈsaku]) or Bussaco was fought on 27 September 1810 during the Peninsular War in the Portuguese mountain range of Serra do Buçaco, resulting in the defeat of French forces by Lord Wellington''s Anglo-Portuguese Army. Having occupied the heights of Bussaco with a total of 26,843 British and 25,429 Portuguese troops, Wellington was attacked five times successively by invasion force of 65,050 French under Marshal André Masséna.', 1810, 9, 27, NULL, NULL, NULL, 'day', '27 September 1810', 47, 'https://en.wikipedia.org/wiki/Battle_of_Bussaco'),
  ('Q2890534', 'Battle of the Côa', 'The Combat of the Côa (July 24, 1810; also referred to as Coa or Cõa) was a military engagement that occurred during the Peninsular War period of the Napoleonic Wars. It took place in the valley of the Côa River and it was the first significant battle for the new army of 65,000 men controlled by Marshal André Masséna, as the French prepared for their third invasion of Portugal.', 1810, 7, 24, NULL, NULL, NULL, 'day', '24 July 1810', 39, 'https://en.wikipedia.org/wiki/Combat_of_the_C%C3%B4a'),
  ('Q3112690', 'Siege of Almeida', 'In the siege of Almeida, Portugal, the French corps of Marshal Michel Ney captured the border fortress from Brigadier General William Cox''s Portuguese garrison. This action was fought in the summer of 1810 during the Peninsular War portion of the Napoleonic Wars.', 1810, 7, 25, 1810, 8, 27, 'day', '25 July 1810 – 27 August 1810', 41, 'https://en.wikipedia.org/wiki/Siege_of_Almeida_(1810)'),
  ('Q1822923', 'Liberal Revolution of 1820', 'The Liberal Revolution of 1820 (Portuguese: Revolução Liberal) was a Portuguese political revolution that erupted in 1820. It began with a military insurrection in the city of Porto, in northern Portugal, that quickly and peacefully spread to the rest of the country.', 1820, 8, 24, NULL, NULL, NULL, 'day', '24 August 1820', 56, 'https://en.wikipedia.org/wiki/Liberal_Revolution_of_1820'),
  ('Q1237867', 'Liberal Wars', 'The Liberal Wars (Portuguese: Guerras Liberais), also known as the Portuguese Civil War (Guerra Civil Portuguesa) and the War of the Two Brothers (Guerra dos Dois Irmãos) was a civil war in Portugal that lasted from May 1828 to May 1834, fought between liberal progressive constitutionalists (led by former King Pedro IV) and conservative traditionalists (led by King Miguel I) over the country''s system of government and royal succession. Embroiled parties included the Kingdom of Portugal, Portuguese rebels, the United Kingdom, France, the Catholic Church, Spain and Russia.', 1828, NULL, NULL, 1834, NULL, NULL, 'year', '1828–1834', 58, 'https://en.wikipedia.org/wiki/Liberal_Wars'),
  ('Q12375644', 'Battle of Cape St. Vincent', 'The Battle of Cape St. Vincent was a naval encounter off Cape St.', 1833, 7, 5, NULL, NULL, NULL, 'day', '5 July 1833', 41, 'https://en.wikipedia.org/wiki/Battle_of_Cape_St._Vincent_(1833)'),
  ('Q760027', 'Revolution of Maria da Fonte', 'The Revolution of Maria da Fonte, or Revolution of the Minho, is the name given to a popular revolt in the spring of 1846 against the Cartista government of Portugal (presided over by António Bernardo da Costa Cabral, 1st Marquess of Tomar). The revolt resulted from social tensions remaining from the Liberal Wars, exacerbated by great popular discontent generated by new military recruitment laws, fiscal alterations and the prohibition on burials inside churches.', 1846, NULL, NULL, NULL, NULL, NULL, 'year', '1846', 41, 'https://en.wikipedia.org/wiki/Revolution_of_Maria_da_Fonte'),
  ('Q638903', '5 October 1910 revolution', 'The 5 October 1910 Revolution (Portuguese: Revolução de 5 de outubro de 1910) was the overthrow of the centuries-old Portuguese monarchy and its replacement by the First Portuguese Republic. It was the result of a coup d''état organized by the Portuguese Republican Party.', 1910, 10, 5, 1910, 10, 5, 'day', '5 October 1910', 70, 'https://en.wikipedia.org/wiki/5_October_1910_revolution'),
  ('Q4412123', 'Monarchy of the North', 'The Monarchy of the North (Portuguese: Monarquia do Norte), officially the Kingdom of Portugal (Reino de Portugal), was a short-lived counter-revolution against the First Portuguese Republic and a monarchist government that was established in Northern Portugal in early 1919. It was based in Porto and lasted from 19 January to 13 February 1919.', 1919, 1, 19, 1919, 2, 14, 'day', '19 January 1919 – 14 February 1919', 48, 'https://en.wikipedia.org/wiki/Monarchy_of_the_North'),
  ('Q641898', 'Bloody Night', 'Bloody Night (Portuguese: Noite Sangrenta) is the name by which the radical revolt that took place in Lisbon, on the night of 19 October 1921, became known. During the day, a coup led António Granjo''s government to resign, but President António José de Almeida resisted appointing the rebels'' government.', 1921, 10, 19, NULL, NULL, NULL, 'day', '19 October 1921', 41, 'https://en.wikipedia.org/wiki/Bloody_Night_(Lisbon%2C_1921)'),
  ('Q732219', '28 May 1926 coup d''état', 'The 28 May 1926 coup d''état, sometimes called 28 May Revolution or, during the period of the corporatist Estado Novo (English: New State), the National Revolution (Portuguese: Revolução Nacional), was a military coup of a nationalist origin, that put an end to the unstable Portuguese First Republic and initiated 48 years of corporatist and nationalist rule within Portugal. The regime that immediately resulted from the coup, the Ditadura Nacional (National Dictatorship), would be later refashioned into the Estado Novo, which in turn lasted until the Carnation Revolution in 1974.', 1926, 5, 28, NULL, NULL, NULL, 'day', '28 May 1926', 50, 'https://en.wikipedia.org/wiki/28_May_1926_coup_d''%C3%A9tat'),
  ('Q884821', 'Iberian Pact', 'The Iberian Pact (Pacto Ibérico) or Peninsular Pact, formally the Portuguese–Spanish Treaty of Friendship and Non-Aggression, was a non-aggression pact that was signed at Lisbon, just a few days before the end of the Spanish Civil War, on 17 March 1939 by Portuguese Prime Minister António de Oliveira Salazar, representing Portugal, and Ambassador Nicolás Franco, representing Spain. The treaty was ratified on 25 March 1939.', 1939, 3, 18, NULL, NULL, NULL, 'day', '18 March 1939', 45, 'https://en.wikipedia.org/wiki/Iberian_Pact'),
  ('Q786906', '1949 Air France Lockheed Constellation crash', 'Air France Flight 009 was a scheduled international flight that crashed into a mountain while attempting to land at Santa Maria Airport, Azores, on 28 October 1949, on a stopover during a scheduled international passenger flight from Paris-Orly Airport to New York City. All 48 people on board were killed.', 1949, 10, 28, NULL, NULL, NULL, 'day', '28 October 1949', 48, 'https://en.wikipedia.org/wiki/Air_France_Flight_009'),
  ('Q4263323', 'Geneva Act of the Lisbon Agreement on Appellations of Origin and Geographical Indications', 'The Lisbon Agreement for the Protection of Appellations of Origin and their International Registration, signed on 31 October 1958, ensures that in member states, appellations of origin receive protection when they are protected in their country of origin. It lays down provisions defining what qualifies as an appellation of origin, sets out protection measures, and establishes an International Register of Appellations of Origin, administered by the World Intellectual Property Organization.', 1958, 10, 31, NULL, NULL, NULL, 'day', '31 October 1958', 43, 'https://en.wikipedia.org/wiki/Lisbon_Agreement_for_the_Protection_of_Appellations_of_Origin_and_their_International_Registration'),
  ('Q60323', 'Viasa Flight 897', 'Viasa Flight 897 was an international scheduled Rome–Madrid–Lisbon–Santa Maria–Caracas passenger service that crashed into the Atlantic Ocean off the coast of Portugal on 30 May 1961, shortly after takeoff from Portela Airport. There were no survivors among the 61 occupants of the Douglas DC-8-53.', 1961, 5, 30, NULL, NULL, NULL, 'day', '30 May 1961', 47, 'https://en.wikipedia.org/wiki/Viasa_Flight_897'),
  ('Q609836', 'Portuguese Colonial War', 'The Portuguese Colonial War (Portuguese: Guerra Colonial Portuguesa), also known in Portugal as the Overseas War (Guerra do Ultramar) or in the former colonies as the War of Liberation (Guerra de Libertação), and also known as the Angolan, Guinea-Bissau and Mozambican Wars of Independence, was a 13-year-long conflict fought between Portugal''s military and the emerging nationalist movements in Portugal''s African colonies between 1961 and 1974. The Portuguese regime at the time, the Estado Novo, was overthrown by a military coup in 1974, and the change in government brought the conflict to an…', 1961, 2, 4, 1974, 4, 25, 'day', '4 February 1961 – 25 April 1974', 69, 'https://en.wikipedia.org/wiki/Portuguese_Colonial_War'),
  ('Q3182793', '12-3 incident', 'The 12-3 incident (Chinese: 一二·三事件; Portuguese: Motim 1-2-3) was a series of political demonstrations and riots against Portuguese colonial rule in Macau which occurred on December 3, 1966. The incident, inspired by the Cultural Revolution in the People''s Republic of China (mainland China), occurred as a direct response to a violent police crackdown by colonial authorities against local Chinese protesters demonstrating against corruption and colonialism in Macau.', 1966, 12, 3, 1967, 1, 28, 'day', '3 December 1966 – 28 January 1967', 45, 'https://en.wikipedia.org/wiki/12-3_incident'),
  ('Q193245', 'Carnation Revolution', 'The Carnation Revolution (Portuguese: Revolução dos Cravos), code-named Operation Historic Turn, also known as the 25 April, and Portuguese Revolution (Portuguese: Revolução Portuguesa) was a military coup in Portugal by officers that on 25 April 1974 overthrew Marcelo Caetano and the Estado Novo regime established by António de Oliveira Salazar (r. 1932–1968).', 1974, 4, 25, NULL, NULL, NULL, 'day', '25 April 1974', 79, 'https://en.wikipedia.org/wiki/Carnation_Revolution'),
  ('Q2853075', 'TAP Portugal Flight 425', 'TAP Flight 425 was a regular scheduled flight from Brussels, Belgium, to Santa Catarina Airport (informally known as Funchal Airport or Madeira Airport; now the Cristiano Ronaldo International Airport), Portugal, with an intermediate scheduled stop in Lisbon. On 19 November 1977, the Boeing 727 operating the service overran the airport''s runway before crashing onto the nearby beach and exploding, killing 131 of the 164 people on board.', 1977, 11, 19, NULL, NULL, NULL, 'day', '19 November 1977', 53, 'https://en.wikipedia.org/wiki/TAP_Flight_425'),
  ('Q3306615', '1980 Azores Islands earthquake', 'Striking the Autonomous Region of the Azores on 1 January, the 1980 Azores Island earthquake killed 73 people and injured over 400, causing severe damage on the islands of Terceira and São Jorge. Resulting from a strike slip fracture, typical of other historical Azorean earthquakes, and measuring 6.9 on the moment magnitude scale, it also shook the islands of Pico and Faial.', 1980, 1, 1, NULL, NULL, NULL, 'day', '1 January 1980', 41, 'https://en.wikipedia.org/wiki/1980_Azores_Islands_earthquake'),
  ('Q349875', '1983 Turkish embassy attack in Lisbon', 'The 1983 Turkish embassy attack was an attack on the Turkish embassy in Lisbon on 27 July 1983, which resulted in the death of 7 people, including all 5 attackers.', 1983, 7, 27, NULL, NULL, NULL, 'day', '27 July 1983', 48, 'https://en.wikipedia.org/wiki/1983_Turkish_embassy_attack_in_Lisbon'),
  ('Q1113432', 'Portuguese Language Orthographic Agreement of 1990', 'The Portuguese-Language Orthographic Agreement of 1990 (Portuguese: Acordo Ortográfico da Língua Portuguesa de 1990) is an international treaty whose purpose is to create a unified orthography for the Portuguese language, to be used by all the countries that have Portuguese as their official language. It was signed in Lisbon, on 16 December 1990, at the end of a negotiation, begun in 1980, between the Sciences Academy of Lisbon and the Brazilian Academy of Letters.', 1990, 12, 16, NULL, NULL, NULL, 'day', '16 December 1990', 50, 'https://en.wikipedia.org/wiki/Portuguese-Language_Orthographic_Agreement_of_1990'),
  ('Q3153850', 'Martinair Flight 495', 'Martinair Flight 495 was a scheduled international flight operated by a McDonnell Douglas DC-10 that crash-landed in severe weather conditions at Faro Airport, Portugal on 21 December 1992. The aircraft carried 13 crew members and 327 passengers, mainly holidaymakers from the Netherlands.', 1992, 12, 21, NULL, NULL, NULL, 'day', '21 December 1992', 52, 'https://en.wikipedia.org/wiki/Martinair_Flight_495'),
  ('Q4263317', 'Lisbon Protocol', 'The Lisbon Protocol to the 1991 Strategic Arms Reduction Treaty was a document signed by representatives of Belarus, Kazakhstan, Russia, and Ukraine that recognized the four states as successors of the Union of Soviet Socialist Republics and all of them assume obligations of the Soviet Union under the START I treaty. These were the four countries in which strategic nuclear weapons of the former Soviet Union remained.', 1992, 5, 23, NULL, NULL, NULL, 'day', '23 May 1992', 53, 'https://en.wikipedia.org/wiki/Lisbon_Protocol'),
  ('Q61000232', 'Air Astana Flight 1388', 'Air Astana Flight 1388 was a repositioning flight from Lisbon to Almaty, with a refueling stop in Minsk. On 11 November 2018, shortly after takeoff, it experienced severe control issues.', 2018, 11, 11, NULL, NULL, NULL, 'day', '11 November 2018', 51, 'https://en.wikipedia.org/wiki/Air_Astana_Flight_1388'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe');
